  (forall a : word, K a -> ~ scratch C s a /\ ~ (data <= bv_unsigned a < data + nd)%Z) ->
  (forall a : word, K a -> mprev a = m0 a) ->
  (forall x : word, ~ (s - 128 <= bv_unsigned x < s - 120)%Z -> N x = mprev x) ->
  (c_top C - LSTK <= s - 128)%Z ->
  (forall a : word, ~ scratch C (s - 128) a -> ~ (data <= bv_unsigned a < data + nd)%Z -> n a = N a) ->
  forall a : word, K a -> n a = m0 a.
